-- Extend Rockmundo interviews with 40 question-specific sets of four answers.
-- Safe to apply directly to live DB and replay through migrations after deployment.
-- Choices: A = genuine, B = considered, C = bold, D = playful.
WITH seed (category, media_types, question_text, a,b,c,d) AS (VALUES
('songwriting', ARRAY['all']::text[], 'When a songwriting session stalls, what do you try next?', 'I take a short break and return with fresh ears.', 'We change instruments and see if a new part appears.', 'I scrap the safe version and try something completely different.', 'I make everyone play the chorus until it begs for mercy.'),
('songwriting', ARRAY['podcast','magazine','radio','tv']::text[], 'If your bandmates dislike a chorus, what happens to it?', 'We listen to the criticism and look for a stronger hook.', 'We record both ideas and let the song decide.', 'I defend it until they show me something better.', 'I hide the demo and hope they forget.'),
('songwriting', ARRAY['all']::text[], 'How do you balance polish against the energy of a first draft?', 'I keep the emotion and fix only what''s distracting.', 'We polish the arrangement without sanding off its character.', 'A rough, fearless take beats a perfect lifeless one.', 'If the tenth edit sounds worse, we blame the coffee.'),
('songwriting', ARRAY['podcast','magazine','newspaper']::text[], 'What makes an opening lyric worth keeping?', 'It sets a feeling that the rest of the song can build on.', 'I test whether it sounds natural when sung aloud.', 'The first line should make people stop what they''re doing.', 'If I have to explain it, I probably rewrite it.'),
('songwriting', ARRAY['all']::text[], 'Would you release a song with an unusual structure?', 'Absolutely, if the strange shape suits the story.', 'We''d test it live before making that decision.', 'I love songs that refuse to behave like singles.', 'Our record label might need a diagram to follow it.'),
('songwriting', ARRAY['podcast','magazine','newspaper']::text[], 'How do you decide who deserves songwriting credit?', 'We agree credits based on genuine contributions.', 'We document ideas early so there''s no confusion later.', 'Nobody gets to erase a bandmate''s creative work.', 'I draw the line at crediting the person who ordered lunch.'),
('songwriting', ARRAY['radio','podcast','tv']::text[], 'Can a long instrumental jam turn into a strong song?', 'Some of our best ideas begin without any lyrics.', 'We record jams and search for the moments worth building on.', 'A riff can say more than three verses.', 'If it lasts twenty minutes, somebody has to write an ending.'),
('songwriting', ARRAY['all']::text[], 'Do you write differently for headphones than for a festival crowd?', 'I want details that reward close listening and big choruses.', 'We consider where a song might live without chasing a format.', 'I write the song first and dare the crowd to follow.', 'The festival version usually has fewer whispered verses.'),
('release_artwork', ARRAY['all']::text[], 'How much can album artwork change the way a record is heard?', 'A strong cover sets the emotional scene before the first track.', 'The artwork should reflect the sound without explaining everything.', 'An iconic image can define a whole musical era.', 'It can also make a terrible album look expensive.'),
('release_artwork', ARRAY['podcast','magazine','internet','newspaper']::text[], 'Would you give a vinyl release its own visual design?', 'Yes, the larger sleeve invites more detail and storytelling.', 'We''d make it distinct while keeping the album identity consistent.', 'I''d turn the record itself into a piece of art.', 'Only if the spinning picture doesn''t make everyone dizzy.'),
('release_artwork', ARRAY['all']::text[], 'How do you choose which songs deserve a place on an album?', 'Every track needs to earn its place in the overall journey.', 'We listen to the running order and look for repetition.', 'I''d cut a popular song if it weakened the record.', 'We draw straws when the arguments reach day three.'),
('release_artwork', ARRAY['radio','podcast','magazine','internet']::text[], 'Would you release a small surprise EP between albums?', 'Yes, if we have songs worth sharing right now.', 'I''d consider it without distracting from the next album.', 'Dropping unexpected music keeps our audience guessing.', 'If the artwork is ready before the songs, maybe.'),
('release_artwork', ARRAY['all']::text[], 'Should the first single sound like the rest of the album?', 'It should give listeners a genuine taste of the record.', 'One single can''t represent every mood on an album.', 'I''d lead with the strangest song to challenge expectations.', 'I''d pick the one our drummer stops complaining about.'),
('release_artwork', ARRAY['podcast','magazine','newspaper','internet']::text[], 'What''s the most important choice in promoting a new release?', 'Give listeners a clear reason to care about the music.', 'Get the timing right and make it easy to discover.', 'A daring performance can speak louder than any advertisement.', 'Not announcing the wrong release date again.'),
('release_artwork', ARRAY['internet','podcast','magazine']::text[], 'Would you trust a fan to design the cover of your next single?', 'I''d love to work with a fan whose art fits the song.', 'We''d agree a fair commission and clear creative direction.', 'An unexpected fan design could be better than the official brief.', 'Only after I check it doesn''t put my face on a potato.'),
('release_artwork', ARRAY['all']::text[], 'Do you still get excited about holding a new CD or vinyl pressing?', 'Absolutely, physical artwork makes a release feel real.', 'It''s a different pleasure from hearing the music online.', 'The first copy feels like proof that the record exists.', 'I mostly hope nobody printed the tracklist upside down.'),
('festival_circuit', ARRAY['radio','tv','podcast','magazine']::text[], 'Would you take an early festival slot if it meant a bigger audience?', 'Yes, every slot is a chance to win people over.', 'I''d weigh the travel and conditions before accepting.', 'Put us on first and we''ll make the next act nervous.', 'As long as the coffee stand is open at sunrise.'),
('festival_circuit', ARRAY['all']::text[], 'How would you win over festival-goers who''ve never heard your band?', 'Start with a song that grabs attention immediately.', 'Play confidently and introduce ourselves between tracks.', 'I''d go all in and make the whole field look up.', 'I might bribe them with the catchiest chorus we have.'),
('festival_circuit', ARRAY['magazine','newspaper','podcast','tv']::text[], 'Should major festivals reserve more space for local bands?', 'Definitely, local scenes help festivals build character.', 'A balanced bill can mix emerging and established acts.', 'A great hometown band deserves a real stage, not a token slot.', 'Let the locals choose one act and watch the crowd show up.'),
('festival_circuit', ARRAY['podcast','magazine','newspaper']::text[], 'How would you handle sharing a festival lineup with a fierce rival?', 'We''d keep it professional and focus on our performance.', 'A little competition can add excitement for the crowd.', 'I''d make sure our set was impossible to follow.', 'I''d check they haven''t taken our dressing-room snacks.'),
('festival_circuit', ARRAY['tv','radio','podcast']::text[], 'Would you cut your set short to play a much bigger festival stage?', 'I would if we could still give the crowd a complete show.', 'It depends on the exposure and the booking terms.', 'Twenty incredible minutes can beat an hour of filler.', 'I''ll play the chorus twice and call it a full set.'),
('festival_circuit', ARRAY['magazine','newspaper','podcast']::text[], 'What could make you reject an otherwise exciting festival booking?', 'Unsafe conditions or unfair treatment of performers.', 'We''d need clear arrangements for pay, travel and equipment.', 'I won''t put the band or fans at risk for a headline.', 'If the stage manager says we have to mime, we''re out.'),
('festival_circuit', ARRAY['radio','tv','podcast']::text[], 'How do you prepare for performing outdoors in awful weather?', 'We check the safety plan and protect the equipment.', 'Our crew would adjust the setup for the conditions.', 'Rain won''t stop the energy if the stage is safe.', 'I''ll bring a towel for every guitar.'),
('festival_circuit', ARRAY['all']::text[], 'Is festival headlining different from leading your own headline show?', 'At a festival, you have to connect with a wider audience fast.', 'Both need good pacing, but the atmosphere is different.', 'A festival crowd challenges you to make thousands of new fans.', 'My own show has fewer surprises from the act before us.'),
('tour_life', ARRAY['podcast','magazine','newspaper']::text[], 'What convinces you to add another city to a tour?', 'Knowing fans there genuinely want to see us.', 'We compare demand with travel costs and the band''s stamina.', 'If a place is hungry for our music, I want to go.', 'If the route looks like a pretzel, maybe not.'),
('tour_life', ARRAY['radio','podcast','magazine']::text[], 'How do you respond when tickets are selling slowly in a city?', 'We reach out to local fans and give the show more attention.', 'I''d review the venue size and promotion plan.', 'I''d rather play hard for fifty people than cancel on them.', 'I resist posting the ticket link every six minutes.'),
('tour_life', ARRAY['podcast','magazine','newspaper']::text[], 'Would you choose two packed club nights over one half-empty arena?', 'Two great club shows can create unforgettable energy.', 'I''d compare the economics and the experience for fans.', 'Give me a room that feels electric, not merely enormous.', 'Two nights means twice the load-in, unfortunately.'),
('tour_life', ARRAY['all']::text[], 'What do you do when a travel delay threatens soundcheck?', 'We keep the promoter informed and work with the crew.', 'We have a shortened setup plan for emergencies.', 'The show goes on if it''s safe and we can play properly.', 'I start doing scales in the back of the van.'),
('tour_life', ARRAY['radio','tv','podcast']::text[], 'Should a hometown concert have a special setlist?', 'I''d bring back a song that means something locally.', 'A few surprises would make it feel personal.', 'The hometown crowd deserves our most ambitious encore.', 'I might play the terrible song we wrote at sixteen.'),
('tour_life', ARRAY['podcast','magazine','newspaper']::text[], 'When does a busy tour need a break rather than another date?', 'When fatigue starts affecting health or the performance.', 'We check in with everyone before adding shows.', 'No booking is worth destroying the band over.', 'When the bassist falls asleep during a soundcheck.'),
('tour_life', ARRAY['all']::text[], 'Would you fly across the world for a single high-profile performance?', 'Yes, if it was a rare opportunity that felt right.', 'We''d balance the exposure against travel impact and cost.', 'One legendary set could change our career.', 'Only if the luggage arrives on the same continent.'),
('tour_life', ARRAY['radio','podcast','magazine']::text[], 'What''s your first ritual when you arrive in a new city on tour?', 'I try to get outside and discover the local music scene.', 'We find the venue, check the schedule, then explore.', 'I look for somewhere we can play an impromptu acoustic set.', 'Locate coffee, food and a working phone charger.'),
('studio_craft', ARRAY['podcast','magazine','radio']::text[], 'Would you record an album in one intense week or spread it over months?', 'I''d like to capture momentum without rushing the songs.', 'We''d choose a schedule that fits the material and budget.', 'One frantic week could give a record a unique edge.', 'Months, so we have time to find the missing cables.'),
('studio_craft', ARRAY['all']::text[], 'Would you keep a technically flawed recording if its emotion was perfect?', 'Yes, feeling is sometimes the whole point.', 'I''d compare it with a cleaner take before deciding.', 'Leave the mistake in if it makes the song human.', 'If the mistake is me coughing, maybe not.'),
('studio_craft', ARRAY['podcast','magazine','radio']::text[], 'When two final mixes both sound good, how do you choose?', 'We listen for the one that supports the song''s emotion.', 'I check them on several systems and ask for fresh ears.', 'I''d pick the mix with the more adventurous sound.', 'We stop voting once nobody can hear a difference.'),
('studio_craft', ARRAY['podcast','magazine','radio']::text[], 'How much experimentation is too much in the studio?', 'When the experiments distract from the song itself.', 'We keep the ideas that actually improve the recording.', 'I''d rather take a wild risk than deliver a forgettable record.', 'When someone asks to record the fridge for percussion.'),
('studio_craft', ARRAY['all']::text[], 'Can a basic home studio make a world-class record?', 'Absolutely, with strong songs and careful listening.', 'Good technique matters more than the price of the room.', 'Limitations can force the most original production choices.', 'Only if the neighbours forgive our drum tracks.'),
('studio_craft', ARRAY['podcast','magazine','newspaper']::text[], 'What makes a recording engineer great to work with?', 'They listen to the artist and solve problems calmly.', 'Clear communication and consistent results matter most.', 'A great engineer knows when to tell us an idea isn''t working.', 'Someone who can find the buzz before my ears melt.'),
('studio_craft', ARRAY['radio','podcast','magazine']::text[], 'Would you add an unfamiliar instrument just to change a song''s mood?', 'Yes, if its sound reveals a new side of the track.', 'I''d invite someone skilled to help us use it well.', 'The wrong instrument in the right place can become magic.', 'I own too many weird instruments to say no.'),
('studio_craft', ARRAY['podcast','magazine','newspaper']::text[], 'Should bandmates hear rough demos before a formal rehearsal?', 'Sharing ideas early gives everyone time to contribute.', 'A rough recording helps people arrive prepared.', 'I''d rather surprise them with the full riff in the room.', 'Yes, but nobody gets to mock my placeholder vocals.')
)
INSERT INTO public.interview_questions
 (category,media_types,question_text,option_a_text,option_a_effects,option_b_text,option_b_effects,option_c_text,option_c_effects,option_d_text,option_d_effects)
SELECT s.category, s.media_types,s.question_text,
s.a, jsonb_build_object('fame_mult',1.03,'fan_mult',1.04,'cash_mult',1.00,'reputation',jsonb_build_object('authentic',2,'professional',1)),
s.b, jsonb_build_object('fame_mult',1.01,'fan_mult',1.02,'cash_mult',1.02,'reputation',jsonb_build_object('diplomatic',2,'professional',2)),
s.c, jsonb_build_object('fame_mult',1.05,'fan_mult',0.99,'cash_mult',0.99,'reputation',jsonb_build_object('bold',2,'rebellious',2)),
s.d, jsonb_build_object('fame_mult',1.02,'fan_mult',1.01,'cash_mult',1.00,'reputation',jsonb_build_object('unpredictable',2,'authentic',1))
FROM seed s
WHERE NOT EXISTS(SELECT 1 FROM public.interview_questions q WHERE lower(btrim(q.question_text))=lower(btrim(s.question_text)));